SELECT c.name, t.name AS type_name, c.max_length, c.precision, c.scale, c.is_nullable, c.is_identity, CAST(IDENT_SEED(N'dbo.Orders') AS bigint) AS identity_seed, CAST(IDENT_INCR(N'dbo.Orders') AS bigint) AS identity_increment, c.is_computed, cc.definition AS computed_definition, dc.definition AS default_definition, c.collation_name FROM sys.columns c JOIN sys.types t ON c.user_type_id = t.user_type_id LEFT JOIN sys.computed_columns cc ON cc.object_id = c.object_id AND cc.column_id = c.column_id LEFT JOIN sys.default_constraints dc ON dc.object_id = c.default_object_id WHERE c.object_id = OBJECT_ID(N'dbo.Orders') ORDER BY c.column_id